export function parseIndicator(text: string): ParsedIndicator | null {
  if (!text) return null;
  const tickerMatch = text.match(TICKER_RE);
  if (!tickerMatch) return null;
  const instrument = tickerMatch[1]!;
  const dimension = indicatorDimension(text);

  for (const { re, op, pickUpper } of PATTERNS) {
    const m = text.match(re);
    if (!m) continue;
    const threshold = parseFloat(m[1]!);
    if (Number.isNaN(threshold)) continue;
    if (pickUpper && m[2]) {
      const upper = parseFloat(m[2]);
      if (Number.isNaN(upper)) continue;
      return { instrument, op, threshold, upper, dimension };
    }
    return { instrument, op, threshold, dimension };
  }
  return null;
}

